// แปลงผลจาก Gemini เป็นรายการที่ตรวจสอบแล้ว (AI อ่านอย่างเดียว ตรวจ/แปลง/คำนวณทำด้วยโค้ด)
const out = $input.first().json;
const ctx = $('Parse Event').first().json;
const me = $('RPC resolve img').first().json;
const fail = (kind, message) => [{ json: { kind, message } }];
const CATS = ['food', 'transport', 'shopping', 'utilities', 'health', 'other'];
const r2 = n => Math.round(n * 100) / 100;
const toNum = v => {
  if (typeof v === 'number') return v;
  const m = String(v ?? '').replace(/,/g, '').match(/\d+(\.\d+)?/);
  return m ? Number(m[0]) : NaN;
};

const raw = (out.content?.parts || []).map(p => p.text || '').join('') || out.text || '';
if (!raw) return fail('ai_failed', 'AI ไม่ตอบกลับ');
let d;
try { d = JSON.parse(String(raw).replace(/```json|```/g, '').trim()); }
catch (e) { return fail('ai_failed', 'อ่านผลจาก AI ไม่ได้'); }
if (d.is_receipt === false) return fail('not_receipt', 'ไม่ใช่ใบเสร็จหรือสลิป');

const items = (Array.isArray(d.items) ? d.items : []).slice(0, 50).map(i => ({
  name: String(i.name || '-').slice(0, 160), qty: Number(i.qty) > 0 ? Number(i.qty) : 1,
  amount: r2(toNum(i.amount) || 0),
  category: CATS.includes(i.category) ? i.category : (CATS.includes(d.category) ? d.category : 'other'),
})).filter(i => i.amount > 0);

let total = r2(toNum(d.total));
if (!(total > 0)) total = r2(items.reduce((s, i) => s + i.amount, 0));
if (!(total > 0)) return fail('invalid', 'อ่านยอดเงินไม่ได้');

const mm = String(d.date || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
let date = null;
if (mm) {
  let y = Number(mm[1]); const mo = Number(mm[2]), da = Number(mm[3]);
  if (y > 2400) y -= 543;
  const t = new Date(Date.UTC(y, mo - 1, da));
  if (t.getUTCFullYear() === y && t.getUTCMonth() === mo - 1 && t.getUTCDate() === da) date = `${y}-${mm[2]}-${mm[3]}`;
}
if (!date) return fail('invalid', 'อ่านวันที่ไม่ได้');

const issues = [];
if (date > $now.toFormat('yyyy-MM-dd')) issues.push(`วันที่อยู่ในอนาคต (${date})`);
let time = String(d.time || '').trim();
if (/^\d{2}:\d{2}:\d{2}$/.test(time)) time = time.slice(0, 5);
if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)) time = null;

// หมวดหลัก = หมวดที่ยอดรวมสูงสุด
const byCat = {};
for (const i of items) byCat[i.category] = (byCat[i.category] || 0) + i.amount;
const top = Object.entries(byCat).sort((a, b) => b[1] - a[1])[0];
const category = top ? top[0] : (CATS.includes(d.category) ? d.category : 'other');

let ref = String(d.reference_no ?? '').trim();
if (ref.length < 4 || ref.length > 64) ref = '';
let conf = Number(d.confidence);
conf = Number.isFinite(conf) ? Math.min(1, Math.max(0, conf)) : 0.5;
if (issues.length) conf = Math.min(conf, 0.5);   // มีข้อสงสัย -> ให้ฐานข้อมูลติดธงรอตรวจ

const path = `${me.workspace_id}/${ctx.arg}.jpg`;
return [{
  json: {
    record: {
      workspace_id: me.workspace_id, submitter_id: me.user_id, ref_no: ref || null,
      txn_date: date, txn_time: time, vendor: String(d.vendor || '').trim().slice(0, 160) || null,
      amount: total, category, items, source: 'line', confidence: conf,
      review_reason: issues.length ? issues.join('; ') : null, image_path: path,
    },
    path,
  },
  binary: $('Get Image').first().binary,
}];

// ทุกสายมารวมที่นี่ สร้างการ์ดตอบตามคำสั่ง (cmd) และผลที่ได้
const ctx = $('Parse Event').first().json;
const res = $input.first().json || {};
const WEB_URL = '';   // ใส่ลิงก์ https ของ dashboard เมื่อ deploy แล้ว จะมีปุ่มเปิดในการ์ด
const GREEN = '#06C755', RED = '#E53935', ORANGE = '#FB8C00';
const ROLE = { admin: 'แอดมิน', accountant: 'ฝ่ายบัญชี', employee: 'พนักงาน' };
const CAT = { food: '🍜 อาหาร', transport: '🚗 เดินทาง', shopping: '🛍️ ช้อปปิ้ง', utilities: '💡 ค่าน้ำไฟ/บริการ', health: '💊 สุขภาพ', other: '📦 อื่นๆ' };
const TH_M = ['', 'ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
const thDate = iso => { const [y, m, d] = String(iso).split('-'); return `${+d} ${TH_M[+m]} ${+y + 543}`; };
const baht = n => Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const HOWTO = ['บอทนี้ใช้ได้เฉพาะคนที่ได้รับเชิญ', 'พิมพ์รหัสเชิญ 6 หลักที่เจ้าของส่งให้ เช่น: ผูก 123456', 'ไม่ต้องล็อกอิน ไม่ต้องกรอกรหัสผ่านหรือข้อมูลส่วนตัวใดๆ'];

function card(color, title, lines, sub, extra, footer) {
  const body = [
    ...lines.map(t => ({ type: 'text', text: t, size: 'sm', wrap: true, color: '#444444' })),
    ...(extra || []),
  ];
  const bubble = {
    type: 'bubble', size: 'kilo',
    header: { type: 'box', layout: 'vertical', backgroundColor: color, paddingAll: '16px', contents: [
      { type: 'text', text: title, color: '#ffffff', weight: 'bold', size: 'md', wrap: true },
      ...(sub ? [{ type: 'text', text: sub, color: '#ffffffcc', size: 'xs', wrap: true, margin: 'sm' }] : []) ] },
    body: { type: 'box', layout: 'vertical', spacing: 'sm', contents: body },
  };
  if (footer && footer.length) bubble.footer = { type: 'box', layout: 'vertical', spacing: 'sm', contents: footer };
  return { type: 'flex', altText: title, contents: bubble };
}

function savedCard(r) {
  const ok = r.status === 'approved';
  const rows = (Array.isArray(r.items) ? r.items : []).slice(0, 6).map(i => ({
    type: 'box', layout: 'horizontal', spacing: 'sm', contents: [
      { type: 'text', text: String(i.name || '-') + (Number(i.qty) > 1 ? ` x${i.qty}` : ''), size: 'xs', color: '#666666', flex: 5, wrap: true },
      { type: 'text', text: `฿${baht(i.amount)}`, size: 'xs', color: '#111111', align: 'end', flex: 2 } ] }));
  if ((r.items || []).length > 6) rows.push({ type: 'text', text: `และอีก ${r.items.length - 6} รายการ`, size: 'xs', color: '#aaaaaa' });
  const extra = [
    { type: 'text', text: r.vendor || 'ไม่ระบุร้าน', weight: 'bold', size: 'lg', wrap: true },
    { type: 'text', text: `฿${baht(r.amount)}`, weight: 'bold', size: 'xxl', color: ok ? GREEN : ORANGE },
    { type: 'text', text: CAT[r.category] || r.category, size: 'sm', color: '#666666' },
    ...(rows.length ? [{ type: 'separator', margin: 'md' }, ...rows] : []),
    ...(r.review_reason ? [{ type: 'text', text: `⚠ ${r.review_reason}`, size: 'xs', color: ORANGE, wrap: true, margin: 'md' }] : []),
  ];
  const footer = /^https:\/\//.test(WEB_URL)
    ? [{ type: 'button', style: 'link', height: 'sm', action: { type: 'uri', label: '🌐 เปิด Dashboard', uri: WEB_URL } }] : [];
  const where = (() => { try { return $('RPC resolve img').first().json.workspace_name; } catch (e) { return ''; } })();
  return card(ok ? GREEN : ORANGE, ok ? '✅ บันทึกสลิปแล้ว' : '⏳ บันทึกแล้ว · รอตรวจ',
    [], `${thDate(r.txn_date)}${r.txn_time ? ' ' + String(r.txn_time).slice(0, 5) : ''}${where ? ' · ' + where : ''}`, extra, footer);
}

function imageCard() {
  if (res.id && res.workspace_id) return savedCard(res);
  if (res.code === '23505') return card(ORANGE, 'ℹ️ สลิปนี้เคยบันทึกแล้ว', ['ระบบพบรหัสอ้างอิงเดียวกันในที่เก็บนี้ จึงไม่บันทึกซ้ำ']);
  if (res.kind === 'not_receipt') return card(RED, '❌ ไม่ใช่ใบเสร็จหรือสลิป', ['ลองถ่ายรูปให้เห็นชื่อร้านและยอดเงินชัดๆ แล้วส่งใหม่']);
  if (res.kind === 'invalid') return card(RED, `❌ ${res.message || 'อ่านข้อมูลไม่ครบ'}`, ['ลองถ่ายรูปให้ชัดขึ้นแล้วส่งใหม่']);
  if (res.kind === 'ai_failed') return card(ORANGE, '⏳ ตอนนี้ AI ติดขัด', ['ลองส่งใหม่อีกครั้งใน 1-2 นาที']);
  if (res.code) return card(RED, '❌ บันทึกไม่สำเร็จ', ['มีข้อผิดพลาดตอนบันทึก ลองส่งใหม่อีกครั้ง']);
  if (!res.user_id) {
    let downloadFailed = false;
    try { downloadFailed = $('Get Image').isExecuted; } catch (e) { /* node ไม่ได้รัน */ }
    return downloadFailed
      ? card(ORANGE, '⏳ ดึงรูปจาก LINE ไม่สำเร็จ', ['ลองส่งรูปใหม่อีกครั้ง'])
      : card(ORANGE, 'ต้องมีรหัสเชิญก่อนส่งสลิป', HOWTO);
  }
  return card(ORANGE, '❌ ประมวลผลไม่สำเร็จ', ['ลองส่งใหม่อีกครั้ง']);
}

let msg;
switch (ctx.cmd) {
  case 'link':
  case 'join':
    if (res.error === 'too_many_attempts')
      msg = card(ORANGE, 'ลองรหัสผิดหลายครั้ง', ['กรุณารอ 10 นาทีแล้วลองใหม่']);
    else if (res.error === 'already_linked')
      msg = card(ORANGE, 'LINE นี้ผูกกับบัญชีอื่นไว้แล้ว', ['ไม่สามารถผูกทับได้', 'ถ้าต้องการเปลี่ยนบัญชี ให้ติดต่อเจ้าของระบบ']);
    else if (res.ok && res.kind === 'join')
      msg = card(GREEN, `✅ เข้าร่วม ${res.workspace_name} แล้ว`, [`บทบาท: ${ROLE[res.role] || res.role}`, 'ส่งรูปสลิปมาได้เลย 📷 สลิปจะเข้าบริษัทนี้', 'พิมพ์ "ใช้ส่วนตัว" เพื่อสลับไปที่เก็บส่วนตัว']);
    else if (res.ok)
      msg = card(GREEN, '✅ เชื่อมบัญชีแล้ว', ['ส่งรูปสลิปมาได้เลย 📷', 'พิมพ์ "ใช้ส่วนตัว" หรือ "ใช้ <ชื่อบริษัท>" เพื่อเลือกที่เก็บ']);
    else
      msg = card(RED, '❌ รหัสไม่ถูกต้องหรือหมดอายุ', ['รหัสเชิญบริษัทใช้ได้ 7 วัน รหัสจากเว็บใช้ได้ 10 นาที และใช้ได้ครั้งเดียว', 'ตรวจเลข 6 หลักแล้วพิมพ์ใหม่ เช่น ผูก 123456']);
    break;
  case 'use':
    if (res.ok) msg = card(GREEN, `✅ ส่งสลิปเข้า ${res.workspace_name}`, ['สลิปที่ส่งจากนี้จะถูกบันทึกที่นี่']);
    else if (res.error === 'not_linked') msg = card(ORANGE, 'ต้องมีรหัสเชิญก่อนใช้งาน', HOWTO);
    else msg = card(ORANGE, 'ไม่พบที่เก็บชื่อนี้', ['ที่ใช้ได้: ' + ((res.options || []).join(', ') || '-'), 'หรือพิมพ์ "ใช้ส่วนตัว"']);
    break;
  case 'image':
    msg = imageCard();
    break;
  default:
    msg = res.user_id
      ? card(GREEN, '👋 พร้อมใช้งาน', [`ที่เก็บตอนนี้: ${res.workspace_name} (${ROLE[res.role] || res.role})`, 'ส่งรูปสลิปมาได้เลย 📷'])
      : card(GREEN, '👋 สวัสดีครับ', [...HOWTO, 'สลิปที่ส่งจะถูกอ่านด้วย AI และเจ้าของบริษัทที่เชิญคุณจะเห็นรายการ']);
}
return [{ json: { replyToken: ctx.replyToken, messages: [msg] } }];
